import { useState, useEffect } from 'react';
import { Table, Button, Input, Select, DatePicker } from 'antd';
import { SearchOutlined, ReloadOutlined, ExportOutlined } from '@ant-design/icons';
import { AlertRecord } from '../types';
import { alertRecords as initialAlertRecords } from '../data/mockData';
import { Dayjs } from 'dayjs';

const { Option } = Select;
const { RangePicker } = DatePicker;

const AllAlerts = () => {
  const [alertRecords] = useState<AlertRecord[]>(initialAlertRecords);
  const [filteredRecords, setFilteredRecords] = useState<AlertRecord[]>(initialAlertRecords);
  const [searchAlertId, setSearchAlertId] = useState('');
  const [searchAlertObject, setSearchAlertObject] = useState('');
  const [searchAlertLocation, setSearchAlertLocation] = useState('');
  const [alertType, setAlertType] = useState('');
  const [alertLevel, setAlertLevel] = useState('');
  const [dateRange, setDateRange] = useState<[Dayjs | null, Dayjs | null] | null>(null);
  const [pagination, setPagination] = useState({ current: 1, pageSize: 20 });

  useEffect(() => {
    let filtered = [...alertRecords];

    if (searchAlertId) {
      filtered = filtered.filter(item =>
        item.alertId.toLowerCase().includes(searchAlertId.toLowerCase())
      );
    }

    if (searchAlertObject) {
      filtered = filtered.filter(item =>
        item.alertObject.toLowerCase().includes(searchAlertObject.toLowerCase())
      );
    }

    if (searchAlertLocation) {
      filtered = filtered.filter(item =>
        item.alertLocation.toLowerCase().includes(searchAlertLocation.toLowerCase())
      );
    }

    if (alertType) {
      filtered = filtered.filter(item => item.alertType === alertType);
    }

    if (alertLevel) {
      filtered = filtered.filter(item => item.alertLevel === alertLevel);
    }

    setFilteredRecords(filtered);
  }, [searchAlertId, searchAlertObject, searchAlertLocation, alertType, alertLevel, dateRange, alertRecords]);

  const handleSearch = () => {
    setPagination({ current: 1, pageSize: 20 });
  };

  const handleReset = () => {
    setSearchAlertId('');
    setSearchAlertObject('');
    setSearchAlertLocation('');
    setAlertType('');
    setAlertLevel('');
    setDateRange(null);
    setPagination({ current: 1, pageSize: 20 });
  };

  const handleExport = () => {
    alert('导出功能');
  };

  const columns = [
    {
      title: '序号',
      dataIndex: 'id',
      key: 'id',
      width: 60,
      render: (_: unknown, __: unknown, index: number) => (pagination.current - 1) * pagination.pageSize + index + 1,
    },
    {
      title: '告警ID',
      dataIndex: 'alertId',
      key: 'alertId',
      ellipsis: true,
      sorter: (a: AlertRecord, b: AlertRecord) => a.alertId.localeCompare(b.alertId),
    },
    {
      title: '告警类型',
      dataIndex: 'alertType',
      key: 'alertType',
      sorter: (a: AlertRecord, b: AlertRecord) => a.alertType.localeCompare(b.alertType),
    },
    {
      title: '告警级别',
      dataIndex: 'alertLevel',
      key: 'alertLevel',
      sorter: (a: AlertRecord, b: AlertRecord) => a.alertLevel.localeCompare(b.alertLevel),
      render: (level: string) => (
        <span className={level === '红色告警' ? 'text-red-600 font-medium' : level === '橙色告警' ? 'text-orange-500 font-medium' : ''}>
          {level}
        </span>
      ),
    },
    {
      title: '告警来源',
      dataIndex: 'alertSource',
      key: 'alertSource',
      sorter: (a: AlertRecord, b: AlertRecord) => a.alertSource.localeCompare(b.alertSource),
    },
    {
      title: '告警对象',
      dataIndex: 'alertObject',
      key: 'alertObject',
      ellipsis: true,
      sorter: (a: AlertRecord, b: AlertRecord) => a.alertObject.localeCompare(b.alertObject),
    },
    {
      title: '告警位置',
      dataIndex: 'alertLocation',
      key: 'alertLocation',
      sorter: (a: AlertRecord, b: AlertRecord) => a.alertLocation.localeCompare(b.alertLocation),
    },
    {
      title: '所属分组',
      dataIndex: 'groupName',
      key: 'groupName',
      sorter: (a: AlertRecord, b: AlertRecord) => a.groupName.localeCompare(b.groupName),
    },
    {
      title: '巡检点位置',
      dataIndex: 'patrolPointLocation',
      key: 'patrolPointLocation',
      ellipsis: true,
      sorter: (a: AlertRecord, b: AlertRecord) => a.patrolPointLocation.localeCompare(b.patrolPointLocation),
    },
    {
      title: '告警时间',
      dataIndex: 'alertTime',
      key: 'alertTime',
      sorter: (a: AlertRecord, b: AlertRecord) => a.alertTime.localeCompare(b.alertTime),
    },
    {
      title: '处理人',
      dataIndex: 'handler',
      key: 'handler',
      sorter: (a: AlertRecord, b: AlertRecord) => a.handler.localeCompare(b.handler),
    },
    {
      title: '处理时间',
      dataIndex: 'handleTime',
      key: 'handleTime',
      sorter: (a: AlertRecord, b: AlertRecord) => a.handleTime.localeCompare(b.handleTime),
    },
    {
      title: '处理结果',
      dataIndex: 'handleResult',
      key: 'handleResult',
      sorter: (a: AlertRecord, b: AlertRecord) => a.handleResult.localeCompare(b.handleResult),
    },
    {
      title: '操作',
      key: 'action',
      width: 150,
      render: () => (
        <div className="flex items-center space-x-2">
          <Button type="link" size="small">详情</Button>
          <Button type="link" size="small">处理</Button>
          <Button type="link" size="small">转工单</Button>
        </div>
      ),
    },
  ];

  const alertTypeOptions = Array.from(new Set(initialAlertRecords.map(record => record.alertType)));
  const alertLevelOptions = Array.from(new Set(initialAlertRecords.map(record => record.alertLevel)));

  return (
    <div className="p-4">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center space-x-4">
          <div className="flex items-center">
            <span className="mr-2 text-gray-600">告警</span>
            <Input
              placeholder="告警ID"
              value={searchAlertId}
              onChange={(e) => setSearchAlertId(e.target.value)}
              onPressEnter={handleSearch}
              style={{ width: 200 }}
            />
          </div>
          <div className="flex items-center">
            <span className="mr-2 text-gray-600">告警时间</span>
            <RangePicker
              value={dateRange}
              onChange={(dates) => setDateRange(dates)}
              style={{ width: 300 }}
            />
          </div>
          <div className="flex items-center">
            <span className="mr-2 text-gray-600">告警对象</span>
            <Input
              placeholder="请输入告警对象名称"
              value={searchAlertObject}
              onChange={(e) => setSearchAlertObject(e.target.value)}
              onPressEnter={handleSearch}
              style={{ width: 200 }}
            />
          </div>
          <div className="flex items-center">
            <span className="mr-2 text-gray-600">告警位置</span>
            <Input
              placeholder="请输入告警位置"
              value={searchAlertLocation}
              onChange={(e) => setSearchAlertLocation(e.target.value)}
              onPressEnter={handleSearch}
              style={{ width: 200 }}
            />
          </div>
        </div>
        <div className="flex items-center space-x-4">
          <div className="flex items-center">
            <span className="mr-2 text-gray-600">告警类型</span>
            <Select
              placeholder="请选择"
              value={alertType}
              onChange={setAlertType}
              style={{ width: 150 }}
            >
              {alertTypeOptions.map(opt => (
                <Option key={opt} value={opt}>{opt}</Option>
              ))}
            </Select>
          </div>
          <div className="flex items-center">
            <span className="mr-2 text-gray-600">告警级别</span>
            <Select
              placeholder="请选择"
              value={alertLevel}
              onChange={setAlertLevel}
              style={{ width: 150 }}
            >
              {alertLevelOptions.map(opt => (
                <Option key={opt} value={opt}>{opt}</Option>
              ))}
            </Select>
          </div>
          <div className="flex items-center space-x-2">
            <Button
              type="primary"
              icon={<SearchOutlined />}
              onClick={handleSearch}
            >
              查询
            </Button>
            <Button
              icon={<ReloadOutlined />}
              onClick={handleReset}
            >
              重置
            </Button>
            <Button
              type="primary"
              icon={<ExportOutlined />}
              onClick={handleExport}
            >
              导出
            </Button>
          </div>
        </div>
      </div>
      <Table
        columns={columns}
        dataSource={filteredRecords}
        rowKey="id"
        pagination={{
          ...pagination,
          total: filteredRecords.length,
          onChange: (page, pageSize) => setPagination({ current: page, pageSize }),
          showSizeChanger: true,
          pageSizeOptions: ['10', '20', '50', '100'],
          showTotal: (total) => `共 ${total} 条`,
        }}
        bordered
        scroll={{ x: 1600 }}
      />
    </div>
  );
};

export default AllAlerts;