import { useState } from 'react';
import { dynamicMonitorMenu, DynamicMonitorMenu } from '../data/dynamicMonitorData';

interface DynamicMonitorSidebarProps {
  selectedKey: string;
  onSelect: (key: string) => void;
}

const iconMap: Record<string, string> = {
  dashboard: '📊',
  env: '🌡️',
  power: '⚡',
  alert: '🔔',
  device: '🖥️',
  org: '👥',
  system: '⚙️',
};

const DynamicMonitorSidebar = ({ selectedKey, onSelect }: DynamicMonitorSidebarProps) => {
  const [openKeys, setOpenKeys] = useState<string[]>(['envCheck', 'powerCheck', 'alertMgmt', 'deviceMgmt', 'orgPermission', 'systemMgmt']);

  const toggleOpen = (key: string) => {
    setOpenKeys((prev) =>
      prev.includes(key) ? prev.filter((k) => k !== key) : [...prev, key]
    );
  };

  const isChildActive = (item: DynamicMonitorMenu) => {
    if (!item.children) return false;
    return item.children.some((c) => c.key === selectedKey);
  };

  const renderItem = (item: DynamicMonitorMenu) => {
    const Icon = iconMap[item.icon] || '📁';
    const isOpen = openKeys.includes(item.key);
    const hasChildren = item.children && item.children.length > 0;
    const isParentActive = isChildActive(item);

    const parentBaseClass = `flex items-center gap-2 px-4 py-2.5 cursor-pointer text-sm transition-colors ${
      isParentActive && !isOpen
        ? 'text-blue-600 bg-blue-50'
        : 'text-gray-700 hover:bg-gray-100'
    }`;

    if (hasChildren) {
      return (
        <div key={item.key}>
          <div className={parentBaseClass} onClick={() => toggleOpen(item.key)}>
            <span className="text-base">{Icon}</span>
            <span className="flex-1">{item.title}</span>
            <span className={`text-gray-400 text-xs transition-transform ${isOpen ? 'rotate-90' : ''}`}>
              ❯
            </span>
          </div>
          {isOpen && (
            <div className="bg-gray-50">
              {item.children!.map((child) => (
                <div
                  key={child.key}
                  className={`pl-11 pr-4 py-2 cursor-pointer text-sm transition-colors ${
                    selectedKey === child.key
                      ? 'text-blue-600 bg-blue-50 font-medium'
                      : 'text-gray-600 hover:text-blue-600 hover:bg-blue-50'
                  }`}
                  onClick={() => onSelect(child.key)}
                >
                  {child.title}
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }

    return (
      <div
        key={item.key}
        className={`flex items-center gap-2 px-4 py-2.5 cursor-pointer text-sm transition-colors ${
          selectedKey === item.key
            ? 'text-blue-600 bg-blue-50 font-medium'
            : 'text-gray-700 hover:bg-gray-100'
        }`}
        onClick={() => onSelect(item.key)}
      >
        <span className="text-base">{Icon}</span>
        <span>{item.title}</span>
      </div>
    );
  };

  return (
    <div className="w-52 bg-white border-r border-gray-200 h-full flex flex-col">
      {/* App Title */}
      <div className="h-14 px-5 flex items-center border-b border-gray-200">
        <span className="text-lg font-semibold text-blue-600">动环监测</span>
      </div>
      {/* Menu */}
      <nav className="flex-1 overflow-auto py-2">
        {dynamicMonitorMenu.map(renderItem)}
      </nav>
    </div>
  );
};

export default DynamicMonitorSidebar;
