// === 监控设备弹窗 ===
const MonitorDeviceModal = ({
  visible,
  onClose,
  ruleName,
  deviceType,
}: {
  visible: boolean;
  onClose: () => void;
  ruleName: string;
  deviceType: string;
}) => {
  const [searchName, setSearchName] = useState('');
  const [searchLocation, setSearchLocation] = useState<string | undefined>(undefined);
  const [searchStatus, setSearchStatus] = useState<string | undefined>(undefined);
  const [searchMsgType, setSearchMsgType] = useState<string | undefined>(undefined);
  const [selectedRowKeys, setSelectedRowKeys] = useState<React.Key[]>([]);

  const filteredDevices = useMemo(() => {
    return monitorDevices.filter((d) => {
      if (searchName && !d.deviceName.toLowerCase().includes(searchName.toLowerCase())) return false;
      if (searchLocation && d.location !== searchLocation) return false;
      if (searchStatus && d.deviceStatus !== searchStatus) return false;
      return true;
    });
  }, [searchName, searchLocation, searchStatus]);

  const resetFilters = () => {
    setSearchName('');
    setSearchLocation(undefined);
    setSearchStatus(undefined);
    setSearchMsgType(undefined);
  };

  const columns = [
    {
      title: '序号',
      key: 'index',
      width: 60,
      render: (_: unknown, __: unknown, idx: number) => idx + 1,
    },
    { title: '设备名称', dataIndex: 'deviceName', key: 'deviceName', width: 200 },
    { title: '产品', dataIndex: 'product', key: 'product', width: 130 },
    { title: '设备类型', dataIndex: 'deviceType', key: 'deviceType', width: 100 },
    {
      title: '设备状态',
      dataIndex: 'deviceStatus',
      key: 'deviceStatus',
      width: 90,
      render: (status: string) => (
        <span
          className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${
            status === '在线'
              ? 'bg-green-50 text-green-600 border border-green-200'
              : 'bg-red-50 text-red-600 border border-red-200'
          }`}
        >
          {status}
        </span>
      ),
    },
    { title: '所在位置', dataIndex: 'location', key: 'location', width: 150 },
    {
      title: '操作',
      key: 'action',
      width: 80,
      render: () => (
        <Button type="link" size="small" danger className="px-1">移除</Button>
      ),
    },
  ];

  return (
    <Modal
      title={`监控设备 - ${ruleName}（${deviceType}）`}
      open={visible}
      onCancel={onClose}
      footer={<Button onClick={onClose}>关闭</Button>}
      width={900}
      destroyOnClose
    >
      {/* Filters */}
      <div className="flex items-center gap-3 flex-wrap mb-4 mt-2">
        <span className="text-sm text-gray-600">设备名称:</span>
        <Input
          placeholder="请输入"
          style={{ width: 160 }}
          value={searchName}
          onChange={(e) => setSearchName(e.target.value)}
          allowClear
        />
        <span className="text-sm text-gray-600 ml-2">所属位置:</span>
        <Select
          allowClear
          placeholder="请选择"
          style={{ width: 160 }}
          value={searchLocation}
          onChange={(v) => setSearchLocation(v)}
          options={monitorDeviceLocations.map((a) => ({ label: a, value: a }))}
        />
        <span className="text-sm text-gray-600 ml-2">设备状态:</span>
        <Select
          allowClear
          placeholder="请选择"
          style={{ width: 120 }}
          value={searchStatus}
          onChange={(v) => setSearchStatus(v)}
          options={monitorDeviceStatuses.map((a) => ({ label: a, value: a }))}
        />
        <span className="text-sm text-gray-600 ml-2">消息类型:</span>
        <Select
          allowClear
          placeholder="请选择"
          style={{ width: 120 }}
          value={searchMsgType}
          onChange={(v) => setSearchMsgType(v)}
          options={monitorDeviceMsgTypes.map((a) => ({ label: a, value: a }))}
        />
        <div className="ml-auto flex items-center gap-2">
          <Button type="primary" icon={<SearchOutlined />}>查询</Button>
          <Button icon={<ReloadOutlined />} onClick={resetFilters}>重置</Button>
          <Button danger>批量删除</Button>
          <Button type="primary">干掉该设备</Button>
        </div>
      </div>

      <Table
        columns={columns}
        dataSource={filteredDevices}
        rowKey="id"
        size="middle"
        bordered
        rowSelection={{
          selectedRowKeys,
          onChange: setSelectedRowKeys,
        }}
        pagination={{
          pageSize: 10,
          showTotal: (total) => `共 ${total} 条`,
          showSizeChanger: false,
        }}
      />
    </Modal>
  );
};

// === 规则表单（新增/编辑共用，按截图1/2/3布局） ===
const RuleForm = ({ form }: { form: ReturnType<typeof Form.useForm>[0] }) => {
  // 监听设备类型变化，联动告警指标
  const deviceType = Form.useWatch('deviceType', form);
  const alertIndicator = Form.useWatch('alertIndicator', form);

  // 当前设备类型对应的告警指标选项
  const indicatorOptions = useMemo(() => {
    if (!deviceType) return [];
    return deviceTypeIndicatorMap[deviceType] || [];
  }, [deviceType]);

  // 当前告警指标是否需要运算符和告警值
  const needOperator = useMemo(() => {
    return !noOperatorIndicators.includes(alertIndicator);
  }, [alertIndicator]);

  // 设备类型变化时，清空告警指标（如果不属于新设备类型的选项）
  const handleDeviceTypeChange = (value: string) => {
    const validIndicators = deviceTypeIndicatorMap[value] || [];
    const currentIndicator = form.getFieldValue('alertIndicator');
    if (currentIndicator && !validIndicators.includes(currentIndicator)) {
      form.setFieldValue('alertIndicator', undefined);
      form.setFieldValue('operator', undefined);
      form.setFieldValue('threshold', undefined);
    }
  };

  return (
    <Form
      form={form}
      layout="vertical"
      preserve={false}
      initialValues={{
        alertLevel: undefined,
        deviceType: undefined,
        alertIndicator: undefined,
        operator: undefined,
        threshold: 0,
        enabled: true,
        duration: 0,
        durationUnit: '分',
        handler: undefined,
        pushMethod: undefined,
        thirdPartyHandler: undefined,
        notifyPeriods: [{ start: dayjs('00:00:00', 'HH:mm:ss'), end: dayjs('23:59:59', 'HH:mm:ss'), weekdays: ['everyday'] }],
      }}
    >
      {/* 基础信息分组 */}
      <div className="mb-2 pb-1 border-b border-gray-200">
        <span className="text-sm font-medium text-gray-700">基础信息</span>
      </div>
      <div className="grid grid-cols-2 gap-x-4">
        <Form.Item
          label="规则名称"
          name="ruleName"
          rules={[{ required: true, message: '请输入规则名称' }]}
          className="col-span-2"
        >
          <Input placeholder="请输入" />
        </Form.Item>

        <Form.Item
          label="告警等级"
          name="alertLevel"
          rules={[{ required: true, message: '请选择告警等级' }]}
        >
          <Select placeholder="请选择" options={alertRuleLevels.map((a) => ({ label: a, value: a }))} />
        </Form.Item>

        <Form.Item label="告警等级编码" name="alertLevelCode">
          <Input placeholder="请输入" />
        </Form.Item>

        <Form.Item
          label="设备类型"
          name="deviceType"
          rules={[{ required: true, message: '请选择设备类型' }]}
        >
          <Select
            placeholder="请选择"
            options={alertRuleDeviceTypes.map((a) => ({ label: a, value: a }))}
            onChange={handleDeviceTypeChange}
          />
        </Form.Item>

        <Form.Item
          label="告警指标"
          name="alertIndicator"
          rules={[{ required: true, message: '请选择告警指标' }]}
        >
          <Select
            placeholder={deviceType ? '请选择' : '请先选择设备类型'}
            options={indicatorOptions.map((a) => ({ label: a, value: a }))}
            disabled={!deviceType}
          />
        </Form.Item>

        {/* 运算符和告警值根据告警指标条件显示 */}
        {needOperator && (
          <>
            <Form.Item
              label="运算符"
              name="operator"
              rules={[{ required: true, message: '请选择运算符' }]}
            >
              <Select placeholder="请选择" options={alertRuleOperators.map((a) => ({ label: a, value: a }))} />
            </Form.Item>

            <Form.Item
              label="告警值"
              name="threshold"
              rules={[{ required: true, message: '请输入告警值' }]}
            >
              <InputNumber className="w-full" placeholder="请输入" />
            </Form.Item>
          </>
        )}

        <Form.Item label="启用状态" name="enabled" valuePropName="checked">
          <Switch checkedChildren="开启" unCheckedChildren="关闭" />
        </Form.Item>

        <Form.Item
          label="持续时间"
          name="duration"
          rules={[{ required: true, message: '请输入持续时间' }]}
        >
          <InputNumber className="w-full" placeholder="请输入" min={0} addonAfter={
            <Form.Item name="durationUnit" noStyle>
              <Select
                style={{ width: 60 }}
                options={alertRuleDurationUnits.map((a) => ({ label: a, value: a }))}
              />
            </Form.Item>
          } />
        </Form.Item>
      </div>

      {/* 告警通知时段分组 */}
      <Form.List name="notifyPeriods">
        {(fields, { add, remove }) => (
          <>
            {/* 标题栏 + 右上角添加按钮 */}
            <div className="mb-2 mt-4 pb-1 border-b border-gray-200 flex items-center justify-between">
              <span className="text-sm font-medium text-gray-700">告警通知时段</span>
              <Button
                type="link"
                className="p-0 h-auto text-blue-600 text-sm"
                onClick={() => add({ start: dayjs('00:00:00', 'HH:mm:ss'), end: dayjs('23:59:59', 'HH:mm:ss'), weekdays: ['everyday'] })}
              >
                +添加时段
              </Button>
            </div>
            {fields.map(({ key, name, ...restField }) => (
              <div key={key} className="border border-gray-200 rounded-md p-3 mb-3 relative">
                {/* 时段标题 + 删除 */}
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-medium text-gray-700">告警时段{name + 1}</span>
                  {fields.length > 1 && (
                    <CloseOutlined
                      className="text-red-500 cursor-pointer"
                      onClick={() => remove(name)}
                    />
                  )}
                </div>
                {/* 开始/结束时间 */}
                <div className="flex items-end gap-2 mb-3">
                  <Form.Item
                    {...restField}
                    name={[name, 'start']}
                    rules={[{ required: true, message: '请选择开始时间' }]}
                    label="开始时间"
                    className="mb-0"
                  >
                    <TimePicker
                      format="HH:mm:ss"
                      placeholder="开始时间"
                      style={{ width: 150 }}
                    />
                  </Form.Item>
                  <span className="text-gray-500 mb-2">至</span>
                  <Form.Item
                    {...restField}
                    name={[name, 'end']}
                    rules={[{ required: true, message: '请选择结束时间' }]}
                    label="结束时间"
                    className="mb-0"
                  >
                    <TimePicker
                      format="HH:mm:ss"
                      placeholder="结束时间"
                      style={{ width: 150 }}
                    />
                  </Form.Item>
                </div>
                {/* 告警日期 */}
                <Form.Item
                  {...restField}
                  name={[name, 'weekdays']}
                  label="告警日期"
                  className="mb-0"
                >
                  <Checkbox.Group options={alertWeekdays} />
                </Form.Item>
              </div>
            ))}
          </>
        )}
      </Form.List>

      {/* 消息推送分组 */}
      <div className="mb-2 mt-4 pb-1 border-b border-gray-200">
        <span className="text-sm font-medium text-gray-700">消息推送</span>
      </div>
      <div className="grid grid-cols-2 gap-x-4">
        <Form.Item
          label="处理方式"
          name="handler"
          rules={[{ required: true, message: '请选择处理方式' }]}
          className="col-span-2"
        >
          <Select placeholder="请选择" options={alertRuleHandlers.map((a) => ({ label: a, value: a }))} />
        </Form.Item>

        <Form.Item
          label="推送方式"
          name="pushMethod"
          rules={[{ required: true, message: '请选择推送方式' }]}
          className="col-span-2"
        >
          <Select placeholder="请选择" options={alertRulePushMethods.map((a) => ({ label: a, value: a }))} />
        </Form.Item>

        <Form.Item
          label="消息接收人"
          name="receiver"
          rules={[{ required: true, message: '请选择消息接收人' }]}
          className="col-span-2"
        >
          <Select
            placeholder="请选择人员"
            mode="multiple"
            options={[
              { label: '魏建国 Jiangguo WEI', value: 'weijianguo' },
              { label: '张三', value: 'zhangsan' },
              { label: '李四', value: 'lisi' },
            ]}
          />
        </Form.Item>
      </div>

      {/* 第三方告警推送分组 */}
      <div className="mb-2 mt-4 pb-1 border-b border-gray-200">
        <span className="text-sm font-medium text-gray-700">第三方告警推送</span>
      </div>
      <div className="grid grid-cols-2 gap-x-4">
        <Form.Item
          label="第三方告警推送处理方式"
          name="thirdPartyHandler"
          rules={[{ required: true, message: '请选择第三方告警推送处理方式' }]}
          className="col-span-2"
        >
          <Select placeholder="请选择" options={alertRuleThirdPartyHandlers.map((a) => ({ label: a, value: a }))} />
        </Form.Item>

        <Form.Item
          label="Url"
          name="url"
          rules={[{ required: true, message: '请输入Url' }]}
          className="col-span-2"
        >
          <Input placeholder="请输入Url" />
        </Form.Item>
      </div>
    </Form>
  );
};

