// === 主组件 ===
const AlertRule = () => {
  const [rules, setRules] = useState<AlertRuleItem[]>(alertRules);
  const [searchName, setSearchName] = useState('');
  const [modalVisible, setModalVisible] = useState(false);
  const [modalMode, setModalMode] = useState<'add' | 'edit'>('add');
  const [editingRule, setEditingRule] = useState<AlertRuleItem | null>(null);
  const [monitorModalVisible, setMonitorModalVisible] = useState(false);
  const [monitorRule, setMonitorRule] = useState<AlertRuleItem | null>(null);
  const [form] = Form.useForm();
  const [editTab, setEditTab] = useState('rule');
  const [selectedGroupKey, setSelectedGroupKey] = useState<string>('all');

  // 自定义分组
  const [customGroups, setCustomGroups] = useState<{ key: string; title: string }[]>([
    { key: 'group-temp', title: '温湿度规则组' },
    { key: 'group-leak', title: '漏水规则组' },
  ]);

  const filteredRules = useMemo(() => {
    return rules.filter((r) => {
      if (searchName && !r.ruleName.toLowerCase().includes(searchName.toLowerCase())) return false;
      // 分组筛选
      if (selectedGroupKey === 'all') return true;
      if (selectedGroupKey.startsWith('type-')) {
        const deviceType = selectedGroupKey.replace('type-', '');
        return r.deviceType === deviceType;
      }
      // 自定义分组筛选（按关键词匹配）
      if (selectedGroupKey === 'group-temp') return r.deviceType === '温湿度';
      if (selectedGroupKey === 'group-leak') return r.deviceType === '漏水监测';
      return true;
    });
  }, [rules, searchName, selectedGroupKey]);

  // 构建分组树数据
  const groupTreeData: DataNode[] = useMemo(() => {
    const typeCountMap: Record<string, number> = {};
    alertRuleDeviceTypes.forEach((t) => {
      typeCountMap[t] = rules.filter((r) => r.deviceType === t).length;
    });

    return [
      {
        title: <span>全部规则 <span className="text-gray-400">({rules.length})</span></span>,
        key: 'all',
        icon: <ApartmentOutlined />,
      },
      {
        title: <span className="text-gray-700">设备类型分组</span>,
        key: 'type-group',
        icon: <FolderOutlined />,
        selectable: false,
        children: alertRuleDeviceTypes.map((t) => ({
          title: <span>{t} <span className="text-gray-400">({typeCountMap[t] || 0})</span></span>,
          key: `type-${t}`,
        })),
      },
      ...(customGroups.length > 0
        ? [{
            title: <span className="text-gray-700">自定义分组</span>,
            key: 'custom-group',
            icon: <FolderOutlined />,
            selectable: false,
            children: customGroups.map((g) => ({
              title: <span>{g.title}</span>,
              key: g.key,
            })),
          }]
        : []),
    ];
  }, [rules, customGroups]);

  const handleAddCustomGroup = () => {
    const name = window.prompt('请输入分组名称');
    if (name && name.trim()) {
      const key = `group-custom-${Date.now()}`;
      setCustomGroups((prev) => [...prev, { key, title: name.trim() }]);
    }
  };

  const levelColorMap: Record<string, string> = {
    紧急: 'bg-red-50 text-red-600 border border-red-200',
    重要: 'bg-orange-50 text-orange-600 border border-orange-200',
    次要: 'bg-yellow-50 text-yellow-600 border border-yellow-200',
    提示: 'bg-blue-50 text-blue-600 border border-blue-200',
  };

  const handleAdd = () => {
    setModalMode('add');
    setEditingRule(null);
    setEditTab('rule');
    form.resetFields();
    setModalVisible(true);
  };

  const handleEdit = (record: AlertRuleItem) => {
    setModalMode('edit');
    setEditingRule(record);
    setEditTab('rule');
    form.setFieldsValue({
      ruleName: record.ruleName,
      alertLevel: record.alertLevel,
      alertLevelCode: '1001',
      deviceType: record.deviceType,
      alertIndicator: record.alertIndicator,
      operator: record.operator,
      threshold: record.threshold,
      enabled: record.enabled,
      duration: 1,
      durationUnit: '分',
      handler: record.handler,
      pushMethod: '系统内消息',
      receiver: ['weijianguo'],
      thirdPartyHandler: '自定义推送',
      url: 'http://10.24.106.4:1101/ioc/web/ioc/api/alarm-log/add?enterpriseId=2043984391443640321&source=POWER ENVIRONMENT&alarmType=TEMPERATURE',
      notifyPeriods: [
        { start: dayjs('00:00:00', 'HH:mm:ss'), end: dayjs('08:00:00', 'HH:mm:ss'), weekdays: ['everyday'] },
        { start: dayjs('08:00:00', 'HH:mm:ss'), end: dayjs('23:59:59', 'HH:mm:ss'), weekdays: ['1', '2', '3', '4', '5'] },
      ],
    });
    setModalVisible(true);
  };

  const handleDelete = (id: number) => {
    setRules((prev) => prev.filter((r) => r.id !== id));
  };

  const handleToggleEnabled = (id: number, enabled: boolean) => {
    setRules((prev) => prev.map((r) => (r.id === id ? { ...r, enabled } : r)));
  };

  const handleSave = async () => {
    try {
      const values = await form.validateFields();
      if (editingRule) {
        setRules((prev) =>
          prev.map((r) => (r.id === editingRule.id ? { ...r, ...values } : r))
        );
      } else {
        const newId = Math.max(...rules.map((r) => r.id), 0) + 1;
        setRules((prev) => [...prev, { id: newId, ...values }]);
      }
      setModalVisible(false);
    } catch {
      // 校验失败
    }
  };

  const handleMonitorDevices = (record: AlertRuleItem) => {
    setMonitorRule(record);
    setMonitorModalVisible(true);
  };

  const resetSearch = () => {
    setSearchName('');
    setSelectedGroupKey('all');
  };

  const columns = [
    {
      title: '序号',
      key: 'index',
      width: 60,
      render: (_: unknown, __: unknown, idx: number) => idx + 1,
    },
    { title: '规则名称', dataIndex: 'ruleName', key: 'ruleName', width: 200, sorter: (a: AlertRuleItem, b: AlertRuleItem) => a.ruleName.localeCompare(b.ruleName) },
    {
      title: '告警等级',
      dataIndex: 'alertLevel',
      key: 'alertLevel',
      width: 90,
      render: (level: string) => (
        <span className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${levelColorMap[level] || ''}`}>
          {level}
        </span>
      ),
    },
    { title: '设备类型', dataIndex: 'deviceType', key: 'deviceType', width: 110 },
    { title: '告警指标', dataIndex: 'alertIndicator', key: 'alertIndicator', width: 150 },
    {
      title: '运算符',
      dataIndex: 'operator',
      key: 'operator',
      width: 90,
      render: (val: string) => val || '-',
    },
    {
      title: '阈值',
      dataIndex: 'threshold',
      key: 'threshold',
      width: 80,
      sorter: (a: AlertRuleItem, b: AlertRuleItem) => (a.threshold ?? 0) - (b.threshold ?? 0),
      render: (val: number) => (val !== undefined && val !== null ? val : '-'),
    },
    { title: '处理方', dataIndex: 'handler', key: 'handler', width: 100 },
    {
      title: '是否启用',
      dataIndex: 'enabled',
      key: 'enabled',
      width: 90,
      render: (enabled: boolean, record: AlertRuleItem) => (
        <Switch
          size="small"
          checked={enabled}
          onChange={(checked) => handleToggleEnabled(record.id, checked)}
        />
      ),
    },
    {
      title: '操作',
      key: 'action',
      width: 260,
      fixed: 'right' as const,
      render: (_: unknown, record: AlertRuleItem) => (
        <Space size="small">
          <Button type="link" size="small" icon={<EditOutlined />} className="px-1" onClick={() => handleEdit(record)}>编辑</Button>
          <Button type="link" size="small" icon={<DesktopOutlined />} className="px-1" onClick={() => handleMonitorDevices(record)}>监控设备</Button>
          {record.enabled ? (
            <Button type="link" size="small" className="px-1 text-orange-500" onClick={() => handleToggleEnabled(record.id, false)}>禁用</Button>
          ) : (
            <Button type="link" size="small" className="px-1 text-green-600" onClick={() => handleToggleEnabled(record.id, true)}>启用</Button>
          )}
          <Button type="link" size="small" danger icon={<DeleteOutlined />} className="px-1" onClick={() => handleDelete(record.id)}>删除</Button>
        </Space>
      ),
    },
  ];

  return (
    <div className="bg-gray-50 min-h-full">
      {/* Top bar (title area) */}
      <div className="bg-white border-b border-gray-200 px-6 py-3">
        <div className="flex items-center gap-2 text-sm text-gray-500">
          <span>动环监测</span>
          <span>/</span>
          <span>告警管理</span>
          <span>/</span>
          <span className="text-gray-800 font-medium">告警规则</span>
        </div>
      </div>

      <div className="p-6 flex gap-4">
        {/* 左侧分组树 */}
        <div className="w-56 flex-shrink-0 bg-white rounded-lg border border-gray-200 overflow-hidden">
          <div className="flex items-center justify-between px-3 py-2.5 border-b border-gray-100">
            <span className="text-sm font-medium text-gray-700">分组</span>
            <Button
              type="link"
              size="small"
              icon={<PlusOutlined />}
              className="p-0 h-auto text-blue-600"
              onClick={handleAddCustomGroup}
            >
              新增
            </Button>
          </div>
          <div className="p-2">
            <Tree
              treeData={groupTreeData}
              selectedKeys={[selectedGroupKey]}
              onSelect={(keys) => {
                if (keys.length > 0) setSelectedGroupKey(keys[0] as string);
              }}
              blockNode
              showIcon
              defaultExpandAll
              className="text-sm"
            />
          </div>
        </div>

        {/* 右侧筛选 + 表格 */}
        <div className="flex-1 min-w-0 bg-white rounded-lg border border-gray-200">
          {/* Filters & Action bar */}
          <div className="px-4 py-3 border-b border-gray-100">
            <div className="flex items-center gap-3 flex-wrap">
              <span className="text-sm text-gray-600">规则名称:</span>
              <Input
                placeholder="请输入"
                style={{ width: 200 }}
                value={searchName}
                onChange={(e) => setSearchName(e.target.value)}
                allowClear
              />
              <div className="ml-auto flex items-center gap-2">
                <Button type="primary" icon={<SearchOutlined />}>查询</Button>
                <Button icon={<ReloadOutlined />} onClick={resetSearch}>重置</Button>
                <Button type="primary" icon={<PlusOutlined />} onClick={handleAdd}>新增</Button>
              </div>
            </div>
          </div>

          {/* Table */}
          <div className="p-4">
            {filteredRules.length === 0 ? (
              <Empty description="暂无数据" />
            ) : (
              <Table
                columns={columns}
                dataSource={filteredRules}
                rowKey="id"
                size="middle"
                bordered
                scroll={{ x: 1300 }}
                pagination={{
                  pageSize: 20,
                  showSizeChanger: true,
                  showTotal: (total) => `共 ${total} 条`,
                }}
              />
            )}
          </div>
        </div>
      </div>

      {/* 新增弹窗（截图1） */}
      <Modal
        title="添加"
        open={modalVisible && modalMode === 'add'}
        onCancel={() => setModalVisible(false)}
        onOk={handleSave}
        okText="保存"
        cancelText="取消"
        width={680}
        destroyOnClose
      >
        <RuleForm form={form} />
      </Modal>

      {/* 编辑弹窗（截图2/3/4，含双Tab） */}
      <Modal
        title="编辑"
        open={modalVisible && modalMode === 'edit'}
        onCancel={() => setModalVisible(false)}
        onOk={handleSave}
        okText="保存"
        cancelText="取消"
        width={680}
        destroyOnClose
      >
        <Tabs
          activeKey={editTab}
          onChange={setEditTab}
          items={[
            {
              key: 'rule',
              label: '规则信息',
              children: <RuleForm form={form} />,
            },
            {
              key: 'log',
              label: '日志',
              children: <LogTab />,
            },
          ]}
        />
      </Modal>

      {/* 监控设备弹窗（截图5） */}
      <MonitorDeviceModal
        visible={monitorModalVisible}
        onClose={() => setMonitorModalVisible(false)}
        ruleName={monitorRule?.ruleName || ''}
        deviceType={monitorRule?.deviceType || ''}
      />
    </div>
  );
};

export default AlertRule;
