import { useState, useEffect } from 'react';
import { Layout } from 'antd';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import AlertTypeList from './components/AlertTypeList';
import AllAlerts from './components/AllAlerts';
import WorkOrderTracking from './components/WorkOrderTracking';
import Workbench from './components/Workbench';
import DynamicMonitor from './components/DynamicMonitor';

const { Content } = Layout;

type AppMode = 'workbench' | 'cockpit' | 'dynamicMonitor';

const pageTitleMap: Record<string, string> = {
  allAlerts: '全部告警',
  alertTypes: '告警类型',
  alertSource: '告警来源',
  alertLevel: '告警级别',
  videoLink: '视频联动',
  workOrder: '工单管理',
  workOrderTracking: '工单追踪',
  sla: 'SLA管理',
  workOrderType: '工单类型',
  workOrderSource: '工单来源',
  serviceGroup: '服务组',
  workOrderLevel: '工单级别',
  workOrderSettings: '工单设置',
  home: '首页',
  cockpit: '驾驶舱',
  overview: '总控总览',
  alertCenter: '告警中心',
  screen: '大屏管理',
  organization: '组织权限',
  system: '系统管理',
  integration: '三方集成',
};

const parseHash = (): AppMode => {
  const hash = window.location.hash.replace('#', '').replace('/', '');
  if (hash === 'cockpit') return 'cockpit';
  if (hash === 'dynamicMonitor') return 'dynamicMonitor';
  return 'workbench';
};

function App() {
  const [appMode, setAppMode] = useState<AppMode>(parseHash());
  const [selectedKey, setSelectedKey] = useState('allAlerts');

  useEffect(() => {
    const handleHashChange = () => {
      setAppMode(parseHash());
    };
    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const navigateTo = (route: string) => {
    window.location.hash = `#/${route}`;
  };

  const renderCockpitContent = () => {
    switch (selectedKey) {
      case 'allAlerts':
        return <AllAlerts />;
      case 'alertTypes':
        return <AlertTypeList />;
      case 'workOrderTracking':
        return <WorkOrderTracking />;
      default:
        return <div className="p-4">请选择左侧菜单</div>;
    }
  };

  // Workbench mode
  if (appMode === 'workbench') {
    return <Workbench onNavigate={navigateTo} />;
  }

  // Dynamic Monitor mode (independent full page)
  if (appMode === 'dynamicMonitor') {
    return <DynamicMonitor />;
  }

  // Cockpit mode (existing layout)
  return (
    <Layout className="h-screen">
      <Sidebar selectedKeys={[selectedKey]} onSelect={setSelectedKey} />
      <Layout>
        <Header title={pageTitleMap[selectedKey] || '智慧总控'} />
        <Content className="bg-gray-50 overflow-auto">
          {renderCockpitContent()}
        </Content>
      </Layout>
    </Layout>
  );
}

export default App;
